import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/mdvcat.html","title":"mdvcat","lang":"en-US","frontmatter":{},"git":{"createdTime":1643372127000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":6}]},"readingTime":{"minutes":0.32,"words":95},"filePathRelative":"mdvcat.md"}`),a={name:`mdvcat.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="mdvcat" tabindex="-1"><a class="header-anchor" href="#mdvcat"><span>mdvcat</span></a></h1><p><a href="./MarkDown.html">MarkDown</a>で、vmdがいい感じだが遅いのとメンテされてなさそうなので、<a href="./photino.html">photino</a>で同じようなものを作ってみた。<a href="./FSharp.html">FSharp</a>製。</p><ul><li><a href="https://github.com/karino2/mdvcat" target="_blank" rel="noopener noreferrer">github: karino2/mdvcat</a></li></ul><p><a href="https://github.com/xoofx/markdig" target="_blank" rel="noopener noreferrer">markdig</a>を使って、<a href="./bulma.html">bulma</a>でそれっぽくレンダリングしてみた。</p><p>パフォーマンスがだいぶ良いので、コマンドラインオプションをつけてhomebrewで公開すれば流行るかもしれない。</p><p>.NETがhomebrewがランタイムをアップデートして動かなくなるのにうんざりしてgoで書き直し。</p><ul><li><a href="https://github.com/karino2/mdvcat_go" target="_blank" rel="noopener noreferrer">karino2/mdvcat_go: mdvcat port to go, using webview_go</a></li></ul><h2 id="usage" tabindex="-1"><a class="header-anchor" href="#usage"><span>usage</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ mdvcat some/path/to/file.md</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>これではhtml片が入っているとレンダリングされる。 自分が書いたjekyllなどのブログのプレビュー用。</p><p>スクリプトも実行されてしまうので、外部からのmdの場合はhtmlをdisableする方が良い。 これは<code>-d</code>オプションで出来る。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ mdvcat -d some/path/to/unknown_file.md</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="percolの組み合わせの為のalias" tabindex="-1"><a class="header-anchor" href="#percolの組み合わせの為のalias"><span>percolの組み合わせの為のalias</span></a></h2><p>.zshrcに以下のように書いて、</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">alias pcpath=&quot;percol | sed &#39;s/:.*\\$//&#39;&quot;</span>
<span class="line">alias pcmdvc=&quot;pcpath | xargs mdvcat&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>以下のように使っている。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ grep -RS &quot;ほげほげ&quot; * |  pcmdvc</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,17)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};